1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件回归保障成功使用编号的复用规则：一次成功使用把使用编号与当时的承诺
10	// 编号、数量绑定（当前时刻不属于绑定内容）；之后复用该编号，只要承诺或数量
11	// 有一项改变即返回 ErrConflict——即使新内容本身非法（空承诺编号、承诺不存在、
12	// 数量为零/负数/超过余量），或新指向的承诺已取消、已确认到期。冲突不扣减
13	// 实物库存、不改变任何承诺的已用数量、不释放占用、不借本次时刻确认原承诺或
14	// 新承诺到期，也不会用新内容覆盖原成功记录。冲突之后以首次成功时的承诺与
15	// 数量原样重试，始终取回最初的完整使用结果；承诺即使已被正常取消或确认到期，
16	// 取回旧结果也不重新开放。这些测试只沿用登记、预留、使用、取消和查询的既有
17	// 公开行为。
18	
19	// usedTwiceStore 构造用户给定的主例：备件 part1 初始十件，c1 承诺五件、c2
20	// 承诺三件（同一到期时刻 expiryOK），u1 已在 c1 成功使用两件。此时实物剩余
21	// 八件，有效占用六件（c1 未用三件 + c2 未用三件），可再承诺两件。返回首次
22	// 使用结果供比对。
23	func usedTwiceStore(t *testing.T) (*Store, Usage) {
24		t.Helper()
25		s := newStore(t)
26		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
27			t.Fatalf("reserve c1: %v", err)
28		}
29		if _, err := s.Reserve("c2", "r1", "part1", 3, expiryOK, nowOK); err != nil {
30			t.Fatalf("reserve c2: %v", err)
31		}
32		first, err := s.Use("u1", "c1", 2, nowOK)
33		if err != nil {
34			t.Fatalf("use u1: %v", err)
35		}
36		return s, first
37	}
38	
39	// assertTwiceState 断言主例数量保持不变：实物八件、有效占用六件、可再承诺
40	// 两件；c1 已用两件、未用三件且有效，c2 已用零件、未用三件且有效。查询时刻
41	// 必须早于两笔承诺的到期时刻（调用方需保证），以免查询本身确认到期。
42	func assertTwiceState(t *testing.T, s *Store, now time.Time) {
43		t.Helper()
44		st, err := s.PartStatus("part1", now)
45		if err != nil {
46			t.Fatalf("part status: %v", err)
47		}
48		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 6 || st.Committable != 2 {
49			t.Fatalf("stock = phys %d / occupied %d / committable %d, want 8/6/2",
50				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
51		}
52		d1, ok1 := detailByID(st, "c1")
53		d2, ok2 := detailByID(st, "c2")
54		if !ok1 || !ok2 {
55			t.Fatalf("commitment detail missing: c1=%v c2=%v", ok1, ok2)
56		}
57		if d1.Status != CommitmentActive || d1.UsedQuantity != 2 || d1.RemainingQuantity != 3 {
58			t.Fatalf("c1 detail = %+v, want active/used=2/remaining=3", d1)
59		}
60		if d2.Status != CommitmentActive || d2.UsedQuantity != 0 || d2.RemainingQuantity != 3 {
61			t.Fatalf("c2 detail = %+v, want active/used=0/remaining=3", d2)
62		}
63	}
64	
65	// TestUsageReuseBindsCommitAndQuantityNotTime 验证成功使用只与承诺编号、数量
66	// 绑定：仅本次提交时刻改变不构成冲突，原样取回首次结果；改数量或改承诺编号
67	// 任一项即冲突，且冲突后原记录与全部数量不变。
68	func TestUsageReuseBindsCommitAndQuantityNotTime(t *testing.T) {
69		s, first := usedTwiceStore(t)
70	
71		// 仅本次当前时刻不同：不是冲突，原样取回首次使用结果，不再次扣减。
72		later := nowOK.Add(5 * day)
73		got, err := s.Use("u1", "c1", 2, later)
74		if err != nil || got != first {
75			t.Fatalf("same content at later time = %+v, err %v; want first result %+v", got, err, first)
76		}
77		assertTwiceState(t, s, later)
78	
79		// 改数量：冲突。
80		if u, err := s.Use("u1", "c1", 1, later); !errors.Is(err, ErrConflict) || u != (Usage{}) {
81			t.Fatalf("changed quantity: usage=%+v err=%v, want ErrConflict with empty result", u, err)
82		}
83		// 改承诺编号：冲突。
84		if u, err := s.Use("u1", "c2", 2, later); !errors.Is(err, ErrConflict) || u != (Usage{}) {
85			t.Fatalf("changed commitment: usage=%+v err=%v, want ErrConflict with empty result", u, err)
86		}
87	
88		// 冲突不扣减、不释放，原成功使用记录不被新内容替换。
89		assertTwiceState(t, s, later)
90		if again, err := s.Use("u1", "c1", 2, later); err != nil || again != first {
91			t.Fatalf("original content after conflicts = %+v, err %v; want first result %+v", again, err, first)
92		}
93	}
94	
95	// TestUsageConflictPrecedenceOverInvalidContent 验证复用成功编号时，编号冲突
96	// 优先于一切新内容自身的校验：空承诺编号、承诺不存在、数量为零/负数/超过
97	// 承诺余量，都返回 ErrConflict，而不是普通参数错误、对象不存在或使用超量；
98	// 一笔本身完全合法的新使用内容（数量恰为余量、或指向 c2 的合法数量）同样按
99	// 冲突处理。所有失败都不得改变数量或替换原成功记录。
100	func TestUsageConflictPrecedenceOverInvalidContent(t *testing.T) {
101		s, first := usedTwiceStore(t)
102		submitAt := nowOK.Add(day)
103	
104		cases := []struct {
105			name     string
106			commitID string
107			quantity int
108		}{
109			{"empty commitment id", "", 2},
110			{"unknown commitment", "cMissing", 2},
111			{"zero quantity", "c1", 0},
112			{"negative quantity", "c1", -4},
113			{"quantity over c1 unused", "c1", 4}, // c1 未用仅三件
114			{"quantity equal to c1 unused is still a change", "c1", 3},
115			{"point to c2 with same quantity", "c2", 2},
116			{"point to c2 with quantity over its unused", "c2", 4},
117		}
118		for _, tc := range cases {
119			t.Run(tc.name, func(t *testing.T) {
120				u, err := s.Use("u1", tc.commitID, tc.quantity, submitAt)
121				if !errors.Is(err, ErrConflict) {
122					t.Fatalf("got %v, want ErrConflict", err)
123				}
124				if u != (Usage{}) {
125					t.Fatalf("conflict returned non-empty usage: %+v", u)
126				}
127			})
128		}
129	
130		// 全部冲突后：实物八、占用六、可承诺二，两笔承诺的已用数量与状态不变。
131		assertTwiceState(t, s, submitAt)
132		c1, _ := s.Commitment("c1")
133		c2, _ := s.Commitment("c2")
134		if c1.Used != 2 || c2.Used != 0 || c1.Canceled || c2.Canceled || c1.Expired || c2.Expired {
135			t.Fatalf("conflicts mutated commitments: c1=%+v c2=%+v", c1, c2)
136		}
137		// 原记录未被任何新内容替换：仍取回首次的 {u1 c1 2}。
138		if got, err := s.Use("u1", "c1", 2, nowOK.Add(2*day)); err != nil || got != first {
139			t.Fatalf("original record replaced: got %+v err %v, want %+v", got, err, first)
140		}
141		// 可再承诺两件仍真实可用。
142		if _, err := s.Reserve("c3", "r1", "part1", 2, expiryOK, submitAt); err != nil {
143			t.Fatalf("reserve remaining committable 2 after conflicts: %v", err)
144		}
145	}
146	
147	// TestUsageConflictPrecedenceOverClosedTarget 验证复用成功编号改指向另一笔
148	// 已取消或已确认到期的承诺时，仍按编号冲突处理，而不是 ErrCommitmentClosed；
149	// 冲突不改变取消/到期结果、不确认到期、不扣减或释放任何数量。
150	func TestUsageConflictPrecedenceOverClosedTarget(t *testing.T) {
151		t.Run("target canceled", func(t *testing.T) {
152			s, _ := usedTwiceStore(t)
153			if _, err := s.Cancel("c2", nowOK); err != nil {
154				t.Fatalf("cancel c2: %v", err)
155			}
156			// 复用 u1 改指向已取消的 c2：编号冲突优先。
157			if _, err := s.Use("u1", "c2", 2, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
158				t.Fatalf("point to canceled commitment: got %v, want ErrConflict", err)
159			}
160			c2, _ := s.Commitment("c2")
161			c1, _ := s.Commitment("c1")
162			if !c2.Canceled || c2.Expired || c2.Used != 0 {
163				t.Fatalf("canceled c2 changed by conflict: %+v", c2)
164			}
165			if c1.Used != 2 || c1.Canceled || c1.Expired {
166				t.Fatalf("c1 changed by conflict: %+v", c1)
167			}
168			// 取消释放 c2 的三件占用：实物仍八件，有效占用仅 c1 的三件。
169			st, _ := s.PartStatus("part1", nowOK.Add(day))
170			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
171				t.Fatalf("stock after conflict = %+v, want phys=8 occupied=3 committable=5", st)
172			}
173			if d, _ := detailByID(st, "c2"); d.Status != CommitmentCanceled {
174				t.Fatalf("c2 status = %q, want canceled", d.Status)
175			}
176		})
177	
178		t.Run("target confirmed expired", func(t *testing.T) {
179			s := newStore(t)
180			// c2 使用更早的到期时刻，先于 c1 到期并已被正常确认。
181			c2Expiry := nowOK.Add(2 * day)
182			if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
183				t.Fatalf("reserve c1: %v", err)
184			}
185			if _, err := s.Reserve("c2", "r1", "part1", 3, c2Expiry, nowOK); err != nil {
186				t.Fatalf("reserve c2: %v", err)
187			}
188			first, err := s.Use("u1", "c1", 2, nowOK)
189			if err != nil {
190				t.Fatalf("use u1: %v", err)
191			}
192			// 由库存查询正常确认 c2 到期，释放三件占用。
193			if _, err := s.PartStatus("part1", c2Expiry); err != nil {
194				t.Fatalf("confirm c2 expiry via query: %v", err)
195			}
196			// 复用 u1 改指向已到期的 c2（提交当前时刻也达到其到期时刻）：仍是冲突。
197			if u, err := s.Use("u1", "c2", 2, c2Expiry); !errors.Is(err, ErrConflict) || u != (Usage{}) {
198				t.Fatalf("point to expired commitment: usage=%+v err=%v, want ErrConflict", u, err)
199			}
200			c2, _ := s.Commitment("c2")
201			c1, _ := s.Commitment("c1")
202			if !c2.Expired || c2.Canceled || c2.Used != 0 {
203				t.Fatalf("expired c2 changed by conflict: %+v", c2)
204			}
205			if c1.Used != 2 || c1.Expired || c1.Canceled {
206				t.Fatalf("c1 changed by conflict: %+v", c1)
207			}
208			// 原内容仍取回首次结果，不再次扣减；c1 到期时刻更晚，冲突未波及它。
209			if got, err := s.Use("u1", "c1", 2, c2Expiry); err != nil || got != first {
210				t.Fatalf("retry original content: got %+v err %v, want %+v", got, err, first)
211			}
212			// 回到 c2 到期前时刻查看：c2 到期确认不可逆，c1 仍有效、占用三件。
213			st, _ := s.PartStatus("part1", c2Expiry.Add(-time.Second))
214			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
215				t.Fatalf("stock = %+v, want phys=8 occupied=3 committable=5", st)
216			}
217			d1, _ := detailByID(st, "c1")
218			d2, _ := detailByID(st, "c2")
219			if d1.Status != CommitmentActive || d1.RemainingQuantity != 3 {
220				t.Fatalf("c1 = %+v, want active/remaining=3", d1)
221			}
222			if d2.Status != CommitmentExpired || d2.RemainingQuantity != 3 {
223				t.Fatalf("c2 = %+v, want expired/remaining=3", d2)
224			}
225		})
226	}
227	
228	// TestUsageConflictAtExpiryConfirmsNeitherCommitment 保护重要边界：两笔承诺
229	// 此前都未确认到期，冲突提交的当前时刻却已达到两笔承诺的到期时刻——该提交
230	// 不能确认任一笔到期。之后按到期前时刻查看仍显示有效与原有占用，按较早时刻
231	// 提交合法的新使用也仍可成功。
232	func TestUsageConflictAtExpiryConfirmsNeitherCommitment(t *testing.T) {
233		s, _ := usedTwiceStore(t)
234		before := expiryOK.Add(-time.Minute)
235	
236		// 当前时刻恰好达到两笔承诺共同的到期时刻：改数量、改承诺各冲突一次。
237		if _, err := s.Use("u1", "c1", 1, expiryOK); !errors.Is(err, ErrConflict) {
238			t.Fatalf("changed quantity at expiry: got %v, want ErrConflict", err)
239		}
240		if _, err := s.Use("u1", "c2", 2, expiryOK); !errors.Is(err, ErrConflict) {
241			t.Fatalf("changed commitment at expiry: got %v, want ErrConflict", err)
242		}
243	
244		// 两笔承诺均未被确认到期，已用数量不变。
245		c1, _ := s.Commitment("c1")
246		c2, _ := s.Commitment("c2")
247		if c1.Expired || c1.Used != 2 || c2.Expired || c2.Used != 0 {
248			t.Fatalf("conflict at expiry confirmed/changed commitments: c1=%+v c2=%+v", c1, c2)
249		}
250		// 回到到期前时刻：库存视图仍是有效状态和八/六/二的数量。
251		assertTwiceState(t, s, before)
252		// 请求视图同样显示两笔均有效、原已用数量不变。
253		view, err := s.RequestView("r1", before)
254		if err != nil {
255			t.Fatalf("request view: %v", err)
256		}
257		want := map[string]struct {
258			status             CommitmentStatus
259			used, remainingQty int
260		}{
261			"c1": {CommitmentActive, 2, 3},
262			"c2": {CommitmentActive, 0, 3},
263		}
264		if len(view.Commitments) != len(want) {
265			t.Fatalf("commitments in view = %d, want 2", len(view.Commitments))
266		}
267		for _, d := range view.Commitments {
268			w, ok := want[d.CommitmentID]
269			if !ok {
270				t.Fatalf("unexpected detail: %+v", d)
271			}
272			if d.Status != w.status || d.UsedQuantity != w.used || d.RemainingQuantity != w.remainingQty {
273				t.Fatalf("%s detail = %+v, want status=%s used=%d remaining=%d",
274					d.CommitmentID, d, w.status, w.used, w.remainingQty)
275			}
276		}
277	
278		// 到期前时刻提交一笔合法的新使用：仍成功并正常扣减（c1 已用三件、
279		// 未用两件；实物七件、有效占用五件、可再承诺两件）。
280		u, err := s.Use("u2", "c1", 1, before)
281		if err != nil {
282			t.Fatalf("new legal use at earlier time after conflict: %v", err)
283		}
284		if u.ID != "u2" || u.CommitmentID != "c1" || u.Quantity != 1 {
285			t.Fatalf("new usage = %+v, want {u2 c1 1}", u)
286		}
287		c1b, _ := s.Commitment("c1")
288		if c1b.Used != 3 || c1b.Expired {
289			t.Fatalf("c1 after new use = %+v, want used=3 not expired", c1b)
290		}
291		st, _ := s.PartStatus("part1", before)
292		if st.PhysicalRemaining != 7 || st.ActiveOccupied != 5 || st.Committable != 2 {
293			t.Fatalf("stock after new use = %+v, want phys=7 occupied=5 committable=2", st)
294		}
295	}
296	
297	// TestUsageRetryAfterConflictReturnsFirstAndNeverReopens 验证冲突之后再以首次
298	// 成功时的承诺与数量提交，取回最初的完整使用结果、不再次扣库存；承诺此前已
299	// 被正常取消或确认到期的，取回旧结果也不重新开放承诺。
300	func TestUsageRetryAfterConflictReturnsFirstAndNeverReopens(t *testing.T) {
301		t.Run("commitment still active", func(t *testing.T) {
302			s, first := usedTwiceStore(t)
303			// 先制造若干冲突（含零数量、指向 c2）。
304			if _, err := s.Use("u1", "c1", 0, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
305				t.Fatalf("zero quantity conflict: %v", err)
306			}
307			if _, err := s.Use("u1", "c2", 2, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
308				t.Fatalf("changed commitment conflict: %v", err)
309			}
310			got, err := s.Use("u1", "c1", 2, nowOK.Add(3*day))
311			if err != nil || got != first {
312				t.Fatalf("original retry = %+v, err %v; want first result %+v", got, err, first)
313			}
314			// 不再次扣库存、不释放，c1 仍是已用两件未用三件。
315			assertTwiceState(t, s, nowOK.Add(3*day))
316		})
317	
318		t.Run("commitment canceled beforehand", func(t *testing.T) {
319			s, first := usedTwiceStore(t)
320			if _, err := s.Cancel("c1", nowOK); err != nil {
321				t.Fatalf("cancel c1: %v", err)
322			}
323			// 冲突与原样重试交错提交。
324			if _, err := s.Use("u1", "c2", 5, nowOK.Add(day)); !errors.Is(err, ErrConflict) {
325				t.Fatalf("conflict pointing at c2: %v", err)
326			}
327			got, err := s.Use("u1", "c1", 2, nowOK.Add(2*day))
328			if err != nil || got != first {
329				t.Fatalf("retry after cancel = %+v, err %v; want first result %+v", got, err, first)
330			}
331			c1, _ := s.Commitment("c1")
332			if !c1.Canceled || c1.Expired || c1.Used != 2 {
333				t.Fatalf("c1 reopened or changed by retry: %+v", c1)
334			}
335			// 取回旧结果不重新开放承诺：新使用仍被拒。
336			if _, err := s.Use("u9", "c1", 1, nowOK.Add(2*day)); !errors.Is(err, ErrCommitmentClosed) {
337				t.Fatalf("new use after old-result retrieval: got %v, want ErrCommitmentClosed", err)
338			}
339		})
340	
341		t.Run("commitment confirmed expired beforehand", func(t *testing.T) {
342			s, first := usedTwiceStore(t)
343			before := expiryOK.Add(-time.Minute)
344			// 由库存查询正常确认两笔承诺到期（c1、c2 同一到期时刻）。
345			if _, err := s.PartStatus("part1", expiryOK); err != nil {
346				t.Fatalf("confirm expiry via query: %v", err)
347			}
348			// 到期时刻的冲突提交。
349			if _, err := s.Use("u1", "c1", 1, expiryOK); !errors.Is(err, ErrConflict) {
350				t.Fatalf("conflict at expiry: %v", err)
351			}
352			// 即使回退到到期前时刻原样取回，也只是返回首次结果。
353			got, err := s.Use("u1", "c1", 2, before)
354			if err != nil || got != first {
355				t.Fatalf("retry at earlier time after expiry = %+v, err %v; want %+v", got, err, first)
356			}
357			c1, _ := s.Commitment("c1")
358			if !c1.Expired || c1.Canceled || c1.Used != 2 {
359				t.Fatalf("c1 reopened or changed by retry: %+v", c1)
360			}
361			// 请求视图在较早时刻仍显示到期，占用为零；旧结果不重新开放承诺。
362			view, _ := s.RequestView("r1", before)
363			for _, d := range view.Commitments {
364				if d.Status != CommitmentExpired {
365					t.Fatalf("%s status = %q, want expired", d.CommitmentID, d.Status)
366				}
367			}
368			if _, err := s.Use("u9", "c1", 1, before); !errors.Is(err, ErrCommitmentClosed) {
369				t.Fatalf("new use after old-result retrieval: got %v, want ErrCommitmentClosed", err)
370			}
371			// 到期只释放未用占用、不补实物：实物八件、有效占用零、可承诺八件。
372			st, _ := s.PartStatus("part1", before)
373			if st.PhysicalRemaining != 8 || st.ActiveOccupied != 0 || st.Committable != 8 {
374				t.Fatalf("stock after expiry+retry = %+v, want phys=8 occupied=0 committable=8", st)
375			}
376			d1, _ := detailByID(st, "c1")
377			if d1.UsedQuantity != 2 || d1.RemainingQuantity != 3 {
378				t.Fatalf("c1 detail = %+v, want used=2 remaining=3", d1)
379			}
380		})
381	}
382	
383	// TestFreshUsageIDRejectsInvalidThenSucceeds 是对照测试：尚未成功使用的新
384	// 编号提交零数量等非法内容仍按普通 ErrInvalidParam（未知承诺为 ErrNotFound）
385	// 处理，提前失败不占用编号，修正为合法数量后同一编号可以正常使用。
386	func TestFreshUsageIDRejectsInvalidThenSucceeds(t *testing.T) {
387		s := newStore(t)
388		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
389			t.Fatalf("reserve: %v", err)
390		}
391	
392		if _, err := s.Use("uFresh", "c1", 0, nowOK); !errors.Is(err, ErrInvalidParam) {
393			t.Fatalf("zero quantity for fresh id: got %v, want ErrInvalidParam", err)
394		}
395		if _, err := s.Use("uFresh", "c1", -1, nowOK); !errors.Is(err, ErrInvalidParam) {
396			t.Fatalf("negative quantity for fresh id: got %v, want ErrInvalidParam", err)
397		}
398		if _, err := s.Use("uEmpty", "", 1, nowOK); !errors.Is(err, ErrInvalidParam) {
399			t.Fatalf("empty commitment id: got %v, want ErrInvalidParam", err)
400		}
401		if _, err := s.Use("uMissing", "cMissing", 1, nowOK); !errors.Is(err, ErrNotFound) {
402			t.Fatalf("unknown commitment: got %v, want ErrNotFound", err)
403		}
404	
405		// 非法/缺失引用的提前失败不占用编号：修正内容后同一编号成功使用。
406		u, err := s.Use("uFresh", "c1", 2, nowOK)
407		if err != nil {
408			t.Fatalf("fresh id succeeds after correction: %v", err)
409		}
410		if u.ID != "uFresh" || u.CommitmentID != "c1" || u.Quantity != 2 {
411			t.Fatalf("usage = %+v, want {uFresh c1 2}", u)
412		}
413		u2, err := s.Use("uMissing", "c1", 1, nowOK)
414		if err != nil {
415			t.Fatalf("previously-not-found id succeeds with valid commitment: %v", err)
416		}
417		if u2.ID != "uMissing" || u2.Quantity != 1 {
418			t.Fatalf("usage = %+v, want {uMissing c1 1}", u2)
419		}
420		c1, _ := s.Commitment("c1")
421		if c1.Used != 3 {
422			t.Fatalf("c1 used = %d, want 3", c1.Used)
423		}
424		st, _ := s.PartStatus("part1", nowOK)
425		if st.PhysicalRemaining != 7 {
426			t.Fatalf("physical remaining = %d, want 7", st.PhysicalRemaining)
427		}
428	
429		// 新编号一旦成功，再改内容提交即为冲突，与上面的普通参数错误形成对照。
430		if _, err := s.Use("uFresh", "c1", 0, nowOK); !errors.Is(err, ErrConflict) {
431			t.Fatalf("successful id with zero quantity after success: got %v, want ErrConflict", err)
432		}
433	}
