48	// assertExcludedInWindow 断言请求在保修期内被故障除外原因拒绝，且直接查询
49	// 与按请求查看的结果一致。
50	func assertExcludedInWindow(t *testing.T, s *Store, requestID string) {
51		t.Helper()
52		e, err := s.Evaluate(requestID, nowOK)
53		if err != nil {
54			t.Fatalf("evaluate %s: %v", requestID, err)
55		}
56		if e.Eligible || !e.Excluded {
57			t.Fatalf("%s: want ineligible and excluded, got %+v", requestID, e)
58		}
59		if len(e.Reasons) != 1 || e.Reasons[0] != ReasonFaultExcluded {
60			t.Fatalf("%s: reasons = %v, want only [fault_code_excluded]", requestID, e.Reasons)
61		}
62		view, err := s.RequestView(requestID, nowOK)
63		if err != nil {
64			t.Fatalf("request view %s: %v", requestID, err)
65		}
66		ve := view.Eligibility
67		if ve.Eligible != e.Eligible || ve.Excluded != e.Excluded || len(ve.Reasons) != len(e.Reasons) {
68			t.Fatalf("%s: view %+v disagrees with evaluate %+v", requestID, ve, e)
69		}
70		for i := range e.Reasons {
71			if ve.Reasons[i] != e.Reasons[i] {
72				t.Fatalf("%s: view reasons %v disagree with %v", requestID, ve.Reasons, e.Reasons)
73			}
74		}
75	}
76	
77	// assertEligibleInWindow 断言请求在保修期内合格、未命中除外，且直接查询
78	// 与按请求查看的结果一致。
79	func assertEligibleInWindow(t *testing.T, s *Store, requestID string) {
80		t.Helper()
81		e, err := s.Evaluate(requestID, nowOK)
82		if err != nil {
83			t.Fatalf("evaluate %s: %v", requestID, err)
84		}
85		if !e.Eligible || e.Excluded || len(e.Reasons) != 0 {
86			t.Fatalf("%s: want eligible with no reasons, got %+v", requestID, e)
87		}
88		view, err := s.RequestView(requestID, nowOK)
89		if err != nil {
90			t.Fatalf("request view %s: %v", requestID, err)
91		}
92		ve := view.Eligibility
93		if ve.Eligible != e.Eligible || ve.Excluded != e.Excluded || len(ve.Reasons) != len(e.Reasons) {
94			t.Fatalf("%s: view %+v disagrees with evaluate %+v", requestID, ve, e)
95		}
96	}
97	
98	// TestRegistrationSnapshotsCallerList 登记成功后以登记当时的清单为准：
99	// 调用方替换或补入自己持有的原清单，不改变已登记产品的除外规则。
100	func TestRegistrationSnapshotsCallerList(t *testing.T) {
101		t.Run("replace original code", func(t *testing.T) {
102			codes := []string{"BROKEN_SEAL"}
103			s := isolationStore(t, codes)
104			mustSubmit(t, s, "rOrig", "BROKEN_SEAL")
105			mustSubmit(t, s, "rReplaced", "NOISE")
106	
107			// 登记完成后把原清单中的除外代码替换成另一代码。
108			codes[0] = "NOISE"
109			p, err := s.Product("p1")
110			if err != nil {
111				t.Fatalf("product: %v", err)
112			}
113			assertExcludedCodes(t, p, "BROKEN_SEAL")
114			// 原除外代码仍被拒绝；替换进来的代码原本不在清单中，应合格。
115			assertExcludedInWindow(t, s, "rOrig")
116			assertEligibleInWindow(t, s, "rReplaced")
117		})
118	
119		t.Run("append code to caller list", func(t *testing.T) {
120			codes := make([]string, 1, 4)
121			codes[0] = "BROKEN_SEAL"
122			s := isolationStore(t, codes)
123			mustSubmit(t, s, "rOrig", "BROKEN_SEAL")
124			mustSubmit(t, s, "rAdded", "LEAK")
125	
126			// 登记完成后向原清单补入代码（含就地扩容的情形）。
127			codes = append(codes, "LEAK")
128			codes = append(codes, "SHORT")
129			p, err := s.Product("p1")
130			if err != nil {
131				t.Fatalf("product: %v", err)
132			}
133			assertExcludedCodes(t, p, "BROKEN_SEAL")
134			assertExcludedInWindow(t, s, "rOrig")
135			assertEligibleInWindow(t, s, "rAdded")
136		})
137	}
138	
139	// TestRetrievedProductMutationIsIsolated 取回产品资料后删除原有代码、加入
140	// 新代码：重新取回的资料、先前取得的另一份资料以及请求资格都继续反映
141	// 登记时的规则。
142	func TestRetrievedProductMutationIsIsolated(t *testing.T) {
143		s := isolationStore(t, []string{"BROKEN_SEAL"})
144		mustSubmit(t, s, "rOrig", "BROKEN_SEAL")
145		mustSubmit(t, s, "rAddedLater", "LATER_CODE")
146	
147		first, err := s.Product("p1")
148		if err != nil {
149			t.Fatalf("first product fetch: %v", err)
150		}
151		retrieved, err := s.Product("p1")
152		if err != nil {
153			t.Fatalf("second product fetch: %v", err)
154		}
155		// 调用方从返回的集合中删除原有代码，再加入一个新代码。
156		delete(retrieved.ExcludedCodes, "BROKEN_SEAL")
157		retrieved.ExcludedCodes["LATER_CODE"] = struct{}{}
158	
159		// 重新取回仍反映登记时规则。
160		again, err := s.Product("p1")
161		if err != nil {
162			t.Fatalf("re-fetch product: %v", err)
163		}
164		assertExcludedCodes(t, again, "BROKEN_SEAL")
165		// 此前已经取得的另一份资料不跟着改变。
166		assertExcludedCodes(t, first, "BROKEN_SEAL")
167		if _, leaked := first.ExcludedCodes["LATER_CODE"]; leaked {
168			t.Fatalf("earlier product copy gained added code: %+v", first.ExcludedCodes)
169		}
170	
171		// 资格不被调用方对取回资料的修改影响：原有代码仍拒绝，新代码仍合格。
172		assertExcludedInWindow(t, s, "rOrig")
173		assertEligibleInWindow(t, s, "rAddedLater")
174	}
175	
176	// TestEvaluateAndRequestViewStayConsistentAfterMutation 直接查询资格与按
177	// 请求查看资格时，合格标记、是否命中除外、拒绝原因必须相互一致，不能出现
178	// 资料显示已除外而请求被放行（或反之）的情况。
179	func TestEvaluateAndRequestViewStayConsistentAfterMutation(t *testing.T) {
180		s := isolationStore(t, []string{"BROKEN_SEAL", "OVERHEAT"})
181		mustSubmit(t, s, "r1", "BROKEN_SEAL")
182		mustSubmit(t, s, "r2", "OVERHEAT")
183		mustSubmit(t, s, "r3", "NOISE")
184	
185		p, _ := s.Product("p1")
186		p.ExcludedCodes["NOISE"] = struct{}{}
187		delete(p.ExcludedCodes, "BROKEN_SEAL")
188	
189		for _, id := range []string{"r1", "r2"} {
190			assertExcludedInWindow(t, s, id)
191		}
192		assertEligibleInWindow(t, s, "r3")
193	
194		// 过保时刻：原除外代码仍同时列出过保与除外两项，两种查询口径一致。
195		e, err := s.Evaluate("r1", t0.Add(31*day))
196		if err != nil {
197			t.Fatalf("evaluate after expiry: %v", err)
198		}
199		if e.Eligible || !e.Excluded || len(e.Reasons) != 2 {
200			t.Fatalf("expired+excluded: got %+v", e)
201		}
202		got := map[RejectionReason]bool{}
203		for _, r := range e.Reasons {
204			got[r] = true
205		}
206		if !got[ReasonWarrantyExpired] || !got[ReasonFaultExcluded] {
207			t.Fatalf("reasons = %v, want warranty_expired and fault_code_excluded", e.Reasons)
208		}
209		view, _ := s.RequestView("r1", t0.Add(31*day))
210		if view.Eligibility.Eligible || !view.Eligibility.Excluded ||
211			len(view.Eligibility.Reasons) != 2 {
212			t.Fatalf("view after expiry disagrees: %+v", view.Eligibility)
213		}
214	}
215	
216	// TestReserveHonorsRegistrationSnapshot 除外清单隔离要落到备件预留结果上：
217	// 备件存在且数量足够、到期时刻合法时，原除外请求仍返回现有的不合格错误，
218	// 不创建承诺、不占用备件；未被登记清单除外的请求（含后来替换或补入的
219	// 代码）仍可正常预留。
220	func TestReserveHonorsRegistrationSnapshot(t *testing.T) {
221		codes := []string{"BROKEN_SEAL"}
222		s := isolationStore(t, codes)
223		mustSubmit(t, s, "rExcl", "BROKEN_SEAL")
224		mustSubmit(t, s, "rReplaced", "NOISE")
225		mustSubmit(t, s, "rAdded", "LEAK")
226	
227		// 登记后替换原清单代码并补入新代码，再尝试预留。
228		codes[0] = "NOISE"
229		codes = append(codes, "LEAK")
230		p, _ := s.Product("p1")
231		p.ExcludedCodes["LEAK"] = struct{}{}
232		delete(p.ExcludedCodes, "BROKEN_SEAL")
233	
234		// 原除外请求：仍返回 ErrIneligible，错误明确列出故障除外原因。
235		_, err := s.Reserve("c-bad", "rExcl", "part1", 2, expiryOK, nowOK)
236		if !errors.Is(err, ErrIneligible) {
237			t.Fatalf("reserve excluded request: got %v, want ErrIneligible", err)
238		}
239		if !strings.Contains(err.Error(), string(ReasonFaultExcluded)) {
240			t.Fatalf("error %q must list fault_code_excluded", err.Error())
241		}
242		// 不创建承诺。
243		if _, err := s.Commitment("c-bad"); !errors.Is(err, ErrNotFound) {
244			t.Fatalf("failed reserve created commitment: %v", err)
245		}
246		// 不占用备件。
247		st, _ := s.PartStatus("part1", nowOK)
248		if st.PhysicalRemaining != 10 || st.ActiveOccupied != 0 || st.Committable != 10 {
249			t.Fatalf("failed reserve occupied stock: %+v", st)
250		}
251		// 失败留痕，且历史中的资格快照仍显示除外。
252		h, _ := s.RequestHistory("rExcl")
253		if len(h) != 1 || h[0].Success || h[0].Error != HistoryErrorIneligible {
254			t.Fatalf("ineligible history: %+v", h)
255		}
256		if h[0].Eligibility == nil || !h[0].Eligibility.Excluded ||
257			len(h[0].Eligibility.Reasons) != 1 ||
258			h[0].Eligibility.Reasons[0] != ReasonFaultExcluded {
259			t.Fatalf("ineligible history snapshot: %+v", h[0].Eligibility)
260		}
261	
262		// 替换/补入进来、原先未被除外的代码：正常预留，各占用 2 件。
263		for _, tc := range []struct{ commit, request string }{
264			{"c-replaced", "rReplaced"},
265			{"c-added", "rAdded"},
266		} {
267			c, err := s.Reserve(tc.commit, tc.request, "part1", 2, expiryOK, nowOK)
268			if err != nil {
269				t.Fatalf("reserve %s: %v", tc.request, err)
270			}
271			if c.Quantity != 2 || c.Used != 0 {
272				t.Fatalf("commitment for %s: %+v", tc.request, c)
273			}
274		}
275		st2, _ := s.PartStatus("part1", nowOK)
276		if st2.PhysicalRemaining != 10 || st2.ActiveOccupied != 4 || st2.Committable != 6 {
277			t.Fatalf("eligible reserves stock math: %+v", st2)
278		}
279	}
280	
281	// TestEmptyExclusionListStaysEmpty 产品以空除外清单登记后，向取回的集合
282	// （或登记入参）加入代码，不能让该产品开始拒绝这个故障。
283	func TestEmptyExclusionListStaysEmpty(t *testing.T) {
284		input := make([]string, 0, 4)
285		s := isolationStore(t, input)
286		mustSubmit(t, s, "r1", "RETROACTIVELY_ADDED")
287	
288		retrieved, _ := s.Product("p1")
289		retrieved.ExcludedCodes["RETROACTIVELY_ADDED"] = struct{}{}
290		input = append(input, "RETROACTIVELY_ADDED")
291	
292		again, _ := s.Product("p1")
293		if len(again.ExcludedCodes) != 0 {
294			t.Fatalf("empty exclusion list gained codes: %+v", again.ExcludedCodes)
295		}
296		assertEligibleInWindow(t, s, "r1")
297	
298		// 合格请求仍可正常预留并占用备件。
299		c, err := s.Reserve("c1", "r1", "part1", 1, expiryOK, nowOK)
300		if err != nil {
301			t.Fatalf("reserve on empty-list product: %v", err)
302		}
303		if c.Quantity != 1 {
304			t.Fatalf("commitment: %+v", c)
305		}
306		st, _ := s.PartStatus("part1", nowOK)
307		if st.ActiveOccupied != 1 || st.Committable != 9 {
308			t.Fatalf("stock after reserve: %+v", st)
309		}
310	}
311	
312	// TestExclusionMatchingRemainsExactAndCaseSensitive 沿用故障代码现有的精确
313	// 匹配方式：不做大小写转换或代码修剪，大小写或首尾空白不同的代码是另一
314	// 个代码，仍应合格。
315	func TestExclusionMatchingRemainsExactAndCaseSensitive(t *testing.T) {
316		s := isolationStore(t, []string{"BROKEN_SEAL"})
317		mustSubmit(t, s, "rLower", "broken_seal")
318		mustSubmit(t, s, "rSpaced", " BROKEN_SEAL ")
319	
320		assertEligibleInWindow(t, s, "rLower")
321		assertEligibleInWindow(t, s, "rSpaced")
322		// 精确匹配的原代码仍被拒绝，确认隔离测试没有放松匹配本身。
323		mustSubmit(t, s, "rExact", "BROKEN_SEAL")
324		assertExcludedInWindow(t, s, "rExact")
325	
326		// 未做转换/修剪的近似代码可正常预留。
327		if _, err := s.Reserve("c-lower", "rLower", "part1", 1, expiryOK, nowOK); err != nil {
328			t.Fatalf("reserve lowercase code: %v", err)
329		}
330		if _, err := s.Reserve("c-exact", "rExact", "part1", 1, expiryOK, nowOK); !errors.Is(err, ErrIneligible) {
331			t.Fatalf("reserve exact excluded code: got %v, want ErrIneligible", err)
332		}
333	}
