218	// TestReserveRetryResultIsImmutable 验证调用方修改首次返回值或重试返回值，
219	// 都不能改变以后取回的首次结果、当前承诺和预留历史。
220	func TestReserveRetryResultIsImmutable(t *testing.T) {
221		s := newStore(t)
222		first, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK)
