279		if st.ActiveOccupied != 4 {
280			t.Fatalf("occupied = %d, want 4", st.ActiveOccupied)
281		}
282		// 成功之后，再用曾经失败过的参数提交即按冲突处理。
283		if _, err := s.Reserve("c1", "r1", "part1", 11, expiryOK, nowOK); !errors.Is(err, ErrConflict) {
