	if st.Committable != 0 {
		t.Fatalf("setup: committable = %d, want 0", st.Committable)
	}
	// 请求此时已过保（保修 30 天，now = 第 31 天），且无库存可承诺。
	retry, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, t0.Add(31*day))
	if err != nil {
		t.Fatalf("retry while expired & out of stock: %v", err)
