399		if err != nil || u2.Quantity != 2 {
400			t.Fatalf("use after expiry: %+v err %v", u2, err)
401		}
402	}
403	
404	func TestCancelReleasesOnlyUnused(t *testing.T) {
405		s := newStore(t)
406		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
407			t.Fatalf("reserve: %v", err)
408		}
409		if _, err := s.Use("u1", "c1", 2, nowOK); err != nil {
410			t.Fatalf("use: %v", err)
411		}
412		// 取消：只释放未用的 3，已用的 2 不回补实物库存。
413		if _, err := s.Cancel("c1", nowOK); err != nil {
414			t.Fatalf("cancel: %v", err)
415		}
416		st, _ := s.PartStatus("part1", nowOK)
417		if st.PhysicalRemaining != 8 {
418			t.Fatalf("physical after cancel = %d, want 8", st.PhysicalRemaining)
419		}
420		if st.ActiveOccupied != 0 || st.Committable != 8 {
421			t.Fatalf("cancel did not release: occupied=%d committable=%d", st.ActiveOccupied, st.Committable)
422		}
423		// 重复取消不增加库存。
424		if _, err := s.Cancel("c1", nowOK); err != nil {
425			t.Fatalf("repeat cancel: %v", err)
426		}
427		st2, _ := s.PartStatus("part1", nowOK)
428		if st2.PhysicalRemaining != 8 || st2.Committable != 8 {
429			t.Fatalf("repeat cancel changed stock: %+v", st2)
430		}
431		// 取消后不能继续使用。
432		if _, err := s.Use("u2", "c1", 1, nowOK); !errors.Is(err, ErrCommitmentClosed) {
433			t.Fatalf("use after cancel: got %v", err)
434		}
435	}
436	
437	func TestExpiryAutoReleasesAndBlocksUse(t *testing.T) {
438		s := newStore(t)
439		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
440			t.Fatalf("reserve: %v", err)
441		}
442		if _, err := s.Use("u1", "c1", 2, nowOK); err != nil {
443			t.Fatalf("use: %v", err)
444		}
445		// 到期时刻之前：仍有效，可使用。
446		if _, err := s.Use("u2", "c1", 1, expiryOK.Add(-time.Second)); err != nil {
447			t.Fatalf("use just before expiry: %v", err)
448		}
449		// 到期时刻：自动失效，余量释放，后续使用被拒。
450		if _, err := s.Use("u3", "c1", 1, expiryOK); !errors.Is(err, ErrCommitmentClosed) {
451			t.Fatalf("use at expiry: got %v", err)
452		}
453		st, _ := s.PartStatus("part1", expiryOK)
454		if st.ActiveOccupied != 0 || st.Committable != 7 {
455			t.Fatalf("expiry did not release: occupied=%d committable=%d", st.ActiveOccupied, st.Committable)
456		}
457		// 查询直接体现失效，无需清理。
458		view, _ := s.RequestView("r1", expiryOK)
459		found := false
460		for _, d := range view.Commitments {
461			if d.CommitmentID == "c1" {
462				found = true
463				if d.Status != CommitmentExpired {
464					t.Fatalf("status = %q, want expired", d.Status)
465				}
466				if d.UsedQuantity != 3 || d.RemainingQuantity != 2 {
467					t.Fatalf("detail: used=%d remaining=%d", d.UsedQuantity, d.RemainingQuantity)
468				}
469			}
470		}
471		if !found {
472			t.Fatal("commitment not found in request view")
473		}
474	}
475	
476	func TestRequestView(t *testing.T) {
477		s := newStore(t)
478		if _, err := s.Reserve("c2", "r1", "part1", 2, expiryOK, nowOK); err != nil {
479			t.Fatalf("reserve: %v", err)
