// Package warranty 是本地保修资格与备件承诺的本地基线。
package warranty

// Ready 表示基线可以运行。
func Ready() bool { return true }

package warranty

import (
	"fmt"
	"time"
)

// HistoryError 是预留提交失败的具体错误类别。
type HistoryError string

const (
	// HistoryErrorInvalidParam 表示入参不合法（如非正数量、到期时刻未晚于当前时刻）。
	HistoryErrorInvalidParam HistoryError = "invalid_param"
	// HistoryErrorConflict 表示提交编号被重复用于不同内容。
	HistoryErrorConflict HistoryError = "conflict"
	// HistoryErrorProductNotFound 表示请求关联的产品尚未登记，资格依据为空。
	HistoryErrorProductNotFound HistoryError = "product_not_found"
	// HistoryErrorPartNotFound 表示预留的备件尚未登记，库存依据为空。
	HistoryErrorPartNotFound HistoryError = "part_not_found"
	// HistoryErrorIneligible 表示请求在当次时刻不满足保修资格。
	HistoryErrorIneligible HistoryError = "ineligible"
	// HistoryErrorInsufficientStock 表示可承诺数量不足。
	HistoryErrorInsufficientStock HistoryError = "insufficient_stock"
)

// StockBasis 是提交处理前的库存依据快照。
type StockBasis struct {
	// PhysicalRemaining 是本次提交处理前的剩余实物库存。
	PhysicalRemaining int
	// ActiveOccupied 是本次提交处理前的有效承诺未用总量。
	ActiveOccupied int
	// Committable 是本次提交处理前的可承诺数量（实物剩余扣除有效占用）。
	Committable int
}

// HistoryRecord 是一次预留提交的处理历史记录。
// 每次首次预留成功及每次失败提交都会留下一条记录；同编号同内容的幂等重试不追加。
type HistoryRecord struct {
	// Seq 是记录在所属请求内的处理次序号，按处理次序严格递增。
	Seq int
	// CommitID 是本次提交的承诺编号。
	CommitID string
	// PartID 是本次提交预留的备件编号。
	PartID string
	// Quantity 是本次提交的数量。
	Quantity int
	// Expiry 是本次提交的到期时刻。
	Expiry time.Time
	// Now 是调用方本次提交给定的当前时刻。
	Now time.Time
	// Success 表示本次提交是否成功。
	Success bool
	// Error 是失败的具体错误类别；成功时为空。
	Error HistoryError
	// Eligibility 是资格依据快照；产品缺失等情况下明确为空（nil），不用合格替代缺失。
	Eligibility *Eligibility
	// StockBasis 是库存依据快照；备件缺失等情况下明确为空（nil），不用零库存替代缺失。
	StockBasis *StockBasis
}

// cloneEligibility 返回资格依据快照的深拷贝（含拒绝原因列表）。
func cloneEligibility(e *Eligibility) *Eligibility {
	if e == nil {
		return nil
	}
	cp := *e
	if len(e.Reasons) > 0 {
		cp.Reasons = append(make([]RejectionReason, 0, len(e.Reasons)), e.Reasons...)
	}
	return &cp
}

// cloneStockBasis 返回库存依据快照的深拷贝。
func cloneStockBasis(b *StockBasis) *StockBasis {
	if b == nil {
		return nil
	}
	cp := *b
	return &cp
}

// appendHistoryLocked 在已持锁的情况下追加一条处理记录。
// 序号按处理次序严格递增；提交时刻相同或前后颠倒都不改变这个次序。
func (s *Store) appendHistoryLocked(requestID string, rec HistoryRecord) {
	rec.Seq = len(s.history[requestID]) + 1
	s.history[requestID] = append(s.history[requestID], rec)
}

// recordInvalidParamLocked 在已持锁的情况下，仅当请求已知时记录一次参数无效失败。
func (s *Store) recordInvalidParamLocked(requestID, commitID, partID string, quantity int, expiry, now time.Time) {
	if requestID == "" {
		return
	}
	if _, ok := s.requests[requestID]; !ok {
		return
	}
	s.appendHistoryLocked(requestID, HistoryRecord{
		CommitID: commitID,
		PartID:   partID,
		Quantity: quantity,
		Expiry:   expiry,
		Now:      now,
		Error:    HistoryErrorInvalidParam,
	})
}

// RequestHistory 返回指定请求的预留处理历史，按处理次序排列，序号严格递增。
// 历史查询不需要提供当前时刻；已知请求没有记录时返回空列表。
// 返回的列表及记录均为副本，调用方修改不会影响已保存的历史与后续查询。
func (s *Store) RequestHistory(requestID string) ([]HistoryRecord, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()

	if _, ok := s.requests[requestID]; !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	src := s.history[requestID]
	out := make([]HistoryRecord, len(src))
	for i, rec := range src {
		cp := rec
		cp.Eligibility = cloneEligibility(rec.Eligibility)
		cp.StockBasis = cloneStockBasis(rec.StockBasis)
		out[i] = cp
	}
	return out, nil
}

package warranty

import (
	"fmt"
	"math"
	"time"
)

// unixEpochToInternal 是 Unix 秒与 time.Time 内部绝对秒之间的固定偏移
// （公元 1 年 1 月 1 日到 1970 年 1 月 1 日的秒数）。
const unixEpochToInternal = 62135596800

// secondsPerDay 是每天的秒数；保修期每天固定二十四小时，与时区无关。
const secondsPerDay = 24 * 60 * 60

// warrantyExpiry 计算保修截止时刻：自购买时刻起完整 days 个二十四小时。
// 不经过 time.Duration（其上限约 106751 天），较长保修期限不会溢出回绕；
// 秒以下精度与购买时刻的时区表示原样保留。days 为正整数但截止时刻超出
// 时间类型的可表示范围时返回 ok=false。
func warrantyExpiry(purchase time.Time, days int) (expiry time.Time, ok bool) {
	d := int64(days)
	if d <= 0 || d > math.MaxInt64/secondsPerDay {
		return time.Time{}, false
	}
	add := d * secondsPerDay
	unix := purchase.Unix()
	// 可表示的最大 Unix 秒为 math.MaxInt64 - unixEpochToInternal；
	// 写成 unix > max-add 避免任何中间量溢出。
	if unix > math.MaxInt64-unixEpochToInternal-add {
		return time.Time{}, false
	}
	return time.Unix(unix+add, int64(purchase.Nanosecond())).In(purchase.Location()), true
}

// RejectionReason 是资格拒绝原因。
type RejectionReason string

const (
	// ReasonPurchaseInFuture 表示购买时刻晚于当前时刻。
	ReasonPurchaseInFuture RejectionReason = "purchase_time_in_future"
	// ReasonWarrantyExpired 表示当前时刻已达到或超过保修截止时刻。
	ReasonWarrantyExpired RejectionReason = "warranty_expired"
	// ReasonFaultExcluded 表示故障代码在除外清单中。
	ReasonFaultExcluded RejectionReason = "fault_code_excluded"
)

// Eligibility 是按请求查询的资格依据与拒绝原因。
type Eligibility struct {
	// RequestID 是请求编号。
	RequestID string
	// ProductID 是产品编号。
	ProductID string
	// FaultCode 是故障代码。
	FaultCode string
	// Eligible 表示在当次时刻是否合格。
	Eligible bool
	// Reasons 列出全部拒绝原因；过保与除外同时成立时会列出两项。
	Reasons []RejectionReason
	// PurchaseTime 是购买时刻（资格依据）。
	PurchaseTime time.Time
	// WarrantyDays 是保修天数（资格依据）。
	WarrantyDays int
	// WarrantyExpiry 是保修截止时刻，自购买时刻起按每天二十四小时计算；
	// 当前时刻达到该时刻即算过保。
	WarrantyExpiry time.Time
	// Excluded 表示故障代码是否命中除外清单。
	Excluded bool
}

// evaluateLocked 在已持锁的情况下计算请求在当前时刻的资格。
// 未知产品返回 ErrNotFound，缺少故障代码返回 ErrInvalidParam。
func (s *Store) evaluateLocked(req *Request, now time.Time) (*Eligibility, error) {
	prod, ok := s.products[req.ProductID]
	if !ok {
		return nil, fmt.Errorf("%w: product %q", ErrNotFound, req.ProductID)
	}
	if req.FaultCode == "" {
		return nil, fmt.Errorf("%w: fault code must not be empty", ErrInvalidParam)
	}
	// 登记时已校验截止时刻可表示，这里一定成功。
	expiry, _ := warrantyExpiry(prod.PurchaseTime, prod.WarrantyDays)
	e := &Eligibility{
		RequestID:      req.ID,
		ProductID:      prod.ID,
		FaultCode:      req.FaultCode,
		PurchaseTime:   prod.PurchaseTime,
		WarrantyDays:   prod.WarrantyDays,
		WarrantyExpiry: expiry,
	}
	if prod.PurchaseTime.After(now) {
		e.Reasons = append(e.Reasons, ReasonPurchaseInFuture)
	}
	if !now.Before(e.WarrantyExpiry) {
		e.Reasons = append(e.Reasons, ReasonWarrantyExpired)
	}
	if _, excluded := prod.ExcludedCodes[req.FaultCode]; excluded {
		e.Excluded = true
		e.Reasons = append(e.Reasons, ReasonFaultExcluded)
	}
	e.Eligible = len(e.Reasons) == 0
	return e, nil
}

// Evaluate 返回指定请求在当前时刻的资格依据与拒绝原因。
// 未知产品或缺少故障代码时明确失败，不产生任何承诺。
func (s *Store) Evaluate(requestID string, now time.Time) (*Eligibility, error) {
	if requestID == "" {
		return nil, fmt.Errorf("%w: request id must not be empty", ErrInvalidParam)
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	req, ok := s.requests[requestID]
	if !ok {
		return nil, fmt.Errorf("%w: request %q", ErrNotFound, requestID)
	}
	return s.evaluateLocked(req, now)
}

